create or replace function norrut_private.get_leaderboard() returns table(username text,distance bigint,runs bigint) language sql stable security definer set search_path='' as $$select r.username,r.distance,r.runs from (select p.username,greatest(0,(s.data->>'best')::bigint) distance,(s.data->>'runs')::bigint runs from public.player_profiles p join public.player_saves s on s.user_id=p.user_id where not exists(select 1 from norrut_private.admin_members a where a.user_id=p.user_id) union all select g.username,coalesce((g.stats->>'best')::bigint,0),coalesce((g.stats->>'runs')::bigint,0) from norrut_private.guest_players g) r order by r.distance desc,lower(r.username) asc;$$;